<?php
namespace qqworld_collector\module\collect_filter; class prefixes extends filter { public function filter($item, $args, $source_link, $html, $type, $item_args, $download_args, $mode) { $always_add = isset($args['always_add']) ? $args['always_add'] : 0; if (preg_match('/^<!--\[empty\]-->/i', $item)) $item = preg_replace('/^<!--\[empty\]-->/i', '', $item); if (!empty($item) || $always_add) { $prefix = isset($args['prefix']) ? $args['prefix'] : ''; $suffix = isset($args['suffix']) ? $args['suffix'] : ''; $item = apply_filters( 'qqworld-collector-collection-project-variable-filter', $prefix, 0 ) . $item . apply_filters( 'qqworld-collector-collection-project-variable-filter', $suffix, 0 ); } return $item; } } ?>